export type TicketStatusV2 = "new" | "open" | "pending_customer" | "on_hold" | "solved" | "closed";

export interface Ticket {
  id: string;
  subject: string;
  status: TicketStatusV2;
  priority: "low" | "normal" | "high" | "urgent";
  requesterEmail: string;
  assigneeId: string | null;
  tags: string[];
  createdAt: Date;
  updatedAt: Date;
}

export interface TicketV1 {
  id: string;
  subject: string;
  status: "open" | "pending" | "closed";
  priority: "low" | "normal" | "high";
  requester: string;
  assignee: string | null;
  created_at: string;
}

const V1_STATUS: Record<TicketStatusV2, TicketV1["status"]> = {
  new: "open",
  open: "open",
  pending_customer: "pending",
  on_hold: "pending",
  solved: "closed",
  closed: "closed",
};

export function toV1(t: Ticket): TicketV1 {
  return {
    id: t.id,
    subject: t.subject,
    status: V1_STATUS[t.status],
    priority: t.priority === "urgent" ? "high" : t.priority,
    requester: t.requesterEmail,
    assignee: t.assigneeId,
    created_at: t.createdAt.toISOString(),
  };
}

export function toV2(t: Ticket) {
  return {
    id: t.id,
    subject: t.subject,
    status: t.status,
    priority: t.priority,
    requester: { email: t.requesterEmail },
    assigneeId: t.assigneeId,
    tags: t.tags,
    createdAt: t.createdAt.toISOString(),
    updatedAt: t.updatedAt.toISOString(),
  };
}

import { Request, Response, NextFunction } from "express";

export const SUPPORTED_VERSIONS = ["2023-06-01", "2024-09-15"] as const;
export type ApiVersion = (typeof SUPPORTED_VERSIONS)[number];

const DEFAULT_VERSION: ApiVersion = "2023-06-01";
const SUNSET: Partial<Record<ApiVersion, string>> = {
  "2023-06-01": "Wed, 01 Oct 2025 00:00:00 GMT",
};

declare global {
  namespace Express {
    interface Request {
      apiVersion: ApiVersion;
    }
  }
}

export function resolveVersion(req: Request, res: Response, next: NextFunction) {
  const requested = req.header("Support-Api-Version");
  const version = requested ?? DEFAULT_VERSION;

  if (!(SUPPORTED_VERSIONS as readonly string[]).includes(version)) {
    res.status(400).json({
      error: "unsupported_api_version",
      requested: version,
      supported: SUPPORTED_VERSIONS,
    });
    return;
  }

  req.apiVersion = version as ApiVersion;
  res.setHeader("Support-Api-Version", version);
  res.vary("Support-Api-Version");

  const sunset = SUNSET[req.apiVersion];
  if (sunset) {
    res.setHeader("Deprecation", "true");
    res.setHeader("Sunset", sunset);
    res.setHeader("Link", '</docs/migrations/2024-09-15>; rel="successor-version"');
  }
  next();
}

import express from "express";
import { resolveVersion } from "./versioning";
import { Ticket, toV1, toV2 } from "./ticketViews";
import { TicketRepository } from "./ticketRepository";

function render(version: string, ticket: Ticket) {
  return version === "2023-06-01" ? toV1(ticket) : toV2(ticket);
}

export function ticketRouter(repo: TicketRepository) {
  const router = express.Router();
  router.use(resolveVersion);

  router.get("/tickets/:id", async (req, res, next) => {
    try {
      const ticket = await repo.findById(req.params.id);
      if (!ticket) return res.status(404).json({ error: "ticket_not_found" });
      res.setHeader("Cache-Control", "private, max-age=30");
      res.json(render(req.apiVersion, ticket));
    } catch (err) {
      next(err);
    }
  });

  router.get("/tickets", async (req, res, next) => {
    try {
      const tickets = await repo.listRecent(50);
      res.json({ data: tickets.map((t) => render(req.apiVersion, t)) });
    } catch (err) {
      next(err);
    }
  });

  return router;
}
